contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: order-packed fields minimal to exercise fillOrder for a long position
    function run(
        address maker,
        bool isCall,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        /* ERC20Asset[] and ERC721Asset[] can't be declared in calldata here due to struct type from C, so pass empty arrays by length  */
        uint256 erc20Count,
        uint256 erc721Count,
        bytes calldata signature,
        uint256[] calldata floorAssetTokenIds
    ) public payable {
        require(duration < 10000 days, "precondition duration too long");
        // Build minimal Order in memory using C.Order struct by calling abi.encode/decoding hack
        // Create empty asset arrays
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](erc20Count);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](erc721Count);

        // encode an Order via abi.encode then decode to get the struct in memory
        bytes memory packed = abi.encode(
            maker,
            isCall,
            true, // isLong = true to test long position behavior
            baseAsset,
            strike,
            premium,
            duration,
            expiration,
            nonce,
            whitelist,
            floorTokens,
            erc20Assets,
            erc721Assets
        );

        // The above packing does not match the exact layout of C.Order; instead construct Order by manual assignment
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // Ensure msg.value is available if caller intends to send ETH for weth-related branches
        if (msg.value > 0) {
            require(address(this).balance >= msg.value, "insufficient balance to forward ETH");
        }

        // Record pre-state: ownerOf for maker should revert unless minted; use try/catch to detect
        bool makerHadTokenBefore;
        try c.ownerOf(uint256(c.hashOrder(order))) returns (address ownerBefore) {
            makerHadTokenBefore = (ownerBefore == maker);
        } catch {
            makerHadTokenBefore = false;
        }

        // Call fillOrder and catch revert
        bool reverted;
        uint256 positionIdReturned;
        try c.fillOrder{value: msg.value}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            reverted = false;
            positionIdReturned = pid;
        } catch {
            reverted = true;
            positionIdReturned = 0;
        }

        // After call: compute orderHash and oppositeOrder hash via public helpers
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 orderId = uint256(orderHash);
        uint256 oppositeId = uint256(oppositeHash);

        // Observe whether tokens were minted: ownerOf(orderId) should equal maker if not reverted
        bool makerHasTokenAfter;
        try c.ownerOf(orderId) returns (address ownerAfter) {
            makerHasTokenAfter = (ownerAfter == maker);
        } catch {
            makerHasTokenAfter = false;
        }

        bool counterpartyHasTokenAfter;
        try c.ownerOf(oppositeId) returns (address ownerAfter2) {
            // counterparty is msg.sender = address(this) as InvMutTest is caller to c
            counterpartyHasTokenAfter = (ownerAfter2 == address(this));
        } catch {
            counterpartyHasTokenAfter = false;
        }

        // Read position expiration for the long position (order is long so long position id is orderId)
        uint256 posExpiration = c.positionExpirations(orderId);

        // Assert the general rule: if fillOrder did not revert then
        //  - maker must not have had the token before and now maker owns the minted token
        //  - the counterparty (msg.sender) must own the opposite position token
        //  - positionExpirations for the long position must be set to a nonzero value
        assert(
            reverted || (
                (
                    // makerHasTokenAfter must be true
                    makerHasTokenAfter
                ) && (
                    // counterparty minted
                    counterpartyHasTokenAfter
                ) && (
                    // expiration recorded and strictly greater than block.timestamp
                    posExpiration != 0
                )
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test behavior of fillOrder regarding premium transfers and unclaimedFees accounting.
    // Note: msg.sender for calls to c will be this contract.
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens,
        uint256 erc20Count,
        uint256 erc721Count,
        bytes calldata signature,
        uint256[] calldata floorAssetTokenIds,
        uint256 ethAmountToSend
    ) public payable {
        // Preconditions to avoid obviously-invalid inputs for the branches we observe
        require(duration < 10000 days, "duration too long");
        require(expiration > block.timestamp, "order expired");
        require(baseAsset != address(0), "baseAsset zero");
        // Ensure this test contract has enough ETH if it will forward ETH to c
        if (ethAmountToSend > 0) {
            require(address(this).balance >= ethAmountToSend, "insufficient balance to forward ETH");
        }

        // Build empty asset arrays of specified lengths
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](erc20Count);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](erc721Count);

        // Construct the Order struct in memory
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // Read pre-state: unclaimed fees for this baseAsset and c balance
        uint256 feesBefore = c.unclaimedFees(baseAsset);
        uint256 cBalanceBefore = address(c).balance;

        // Call fillOrder and capture if it reverted
        bool reverted;
        try c.fillOrder{value: ethAmountToSend}(order, signature, floorAssetTokenIds) returns (uint256 pid) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state values
        uint256 feesAfter = c.unclaimedFees(baseAsset);
        uint256 cBalanceAfter = address(c).balance;

        // Compute expected fee amount according to contract logic: fee rate is c.fee() per mille
        uint256 feeRate = c.fee();
        uint256 expectedFee = 0;
        if (feeRate > 0) {
            // safe multiplication: premium * feeRate / 1000
            expectedFee = (premium * feeRate) / 1000;
        }

        // General rule to assert:
        // If fillOrder did not revert then
        //   - the change in unclaimedFees for baseAsset equals expectedFee
        //   - the net ETH balance on c increased by expectedFee when weth == baseAsset and ETH was sent into c via deposit path
        //   - OR if baseAsset is not weth (or no ETH forwarded), c's ether balance change equals 0 (ERC20 flows don't affect ether balance)
        // We observe weth address via c.weth()

        address wethAddr = c.weth();

        // Now assert the general relation (single assert required)
        assert(
            reverted || (
                feesAfter == feesBefore + expectedFee &&
                (
                    // If baseAsset is weth and the call likely used msg.value to deposit into WETH, then c's ETH balance increases by expectedFee when fee was taken into contract.
                    // It's acceptable that cBalance may also increase by premium in some branches; we only assert the delta equals expectedFee when weth==baseAsset and ethAmountToSend>0,
                    // otherwise cBalance should not increase because ERC20 transfers don't change ETH balance of c.
                    (
                        wethAddr == baseAsset && ethAmountToSend > 0
                    ) ? (cBalanceAfter == cBalanceBefore + expectedFee) : (cBalanceAfter == cBalanceBefore)
                )
            )
        );
    }

    receive() external payable {}
}

