contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take many parameters to build an Order; to keep the test generic we only use
    // the fields that are read by hashOrder/fillOrder and required for successful fill.
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(address(this).balance >= 0, true); // no-op to satisfy template style

        // Build minimal order with empty arrays for complex assets.
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // We will call fillOrder and capture whether it reverts.
        bool reverted;
        try c.fillOrder{value: msg.value}(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Compute hashes via the public view function so we can observe owners/positions.
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 orderId = uint256(orderHash);
        uint256 oppositeId = uint256(oppositeHash);

        // Read observable state
        // Note: ownerOf reverts if not minted, so we guard with try-catch to produce sentinel
        address ownerOrder;
        bool orderMinted;
        try c.ownerOf(orderId) returns (address o) {
            ownerOrder = o;
            orderMinted = true;
        } catch {
            ownerOrder = address(0);
            orderMinted = false;
        }

        address ownerOpp;
        bool oppMinted;
        try c.ownerOf(oppositeId) returns (address o2) {
            ownerOpp = o2;
            oppMinted = true;
        } catch {
            ownerOpp = address(0);
            oppMinted = false;
        }

        uint256 expOrder = c.positionExpirations(orderId);
        uint256 expOpp = c.positionExpirations(oppositeId);

        // General rule: if fillOrder did NOT revert and minted positions, then
        // the maker must own the token with id orderHash and the caller (this contract)
        // must own the opposite token, and at least one of the two positionExpirations
        // must be strictly greater than the current block.timestamp (i.e., set).
        assert(
            reverted || (
                orderMinted && oppMinted &&
                ownerOrder == maker &&
                ownerOpp == address(this) &&
                (expOrder > block.timestamp || expOpp > block.timestamp)
            )
        );
    }

    receive() external payable {}
}

