contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe ERC20 balances via public ERC20.balanceOf and c.unclaimedFees and address(c).balance.
    // To avoid depending on any particular ERC20 token contract behavior, we pick baseAsset as an arbitrary address
    // and then only assert relationships when baseAsset != address(0) and is a contract (checked via code.length>0 using public view call).

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        uint256 ethValue
    ) public payable {
        // ensure we can send ETH if needed
        require(address(this).balance >= ethValue, "not enough balance for ethValue");

        // construct minimal order with empty arrays
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        // compute order hash beforehand via view
        bytes32 orderHash = c.hashOrder(order);

        // read pre-state: unclaimedFees for baseAsset
        uint256 preFees = c.unclaimedFees(baseAsset);

        // We'll try to call fillOrder; capture whether it reverted
        bool reverted;
        try c.fillOrder{value: ethValue}(order, "", new uint256[](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 postFees = c.unclaimedFees(baseAsset);

        // If call reverted, nothing required. If succeeded, then fee (if any) was added to unclaimedFees
        // We cannot read ERC20 token balances reliably for arbitrary token addresses, but contract exposes fee and unclaimedFees.
        // Derive expected fee increment: if c.fee>0 then feeAmount = (premium * fee)/1000 else 0.
        uint256 feePercent = c.fee();
        uint256 expectedFee = 0;
        if (feePercent > 0) {
            expectedFee = (premium * feePercent) / 1000;
        }

        // General rule: if fillOrder succeeded then postFees == preFees + expectedFee
        // (covers path where contract collects fee from payer into unclaimedFees)
        assert(
            reverted || (postFees == preFees + expectedFee)
        );
    }

    receive() external payable {}
}

